import { createFileRoute } from "@tanstack/react-router"

import { Badge } from "@tecton/react/components/badge"
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderEyebrow,
  PageHeaderTitle,
} from "@tecton/react/tecton/page-header"

import ColorScaleField from "@/explore/color-scale/v01-field"
import ColorScaleLegendPopover from "@/explore/color-scale/v02-legend-popover"
import ColorScaleStopEditor from "@/explore/color-scale/v03-stop-editor"
